<?php session_start(); require_once __DIR__.'/functions.php'; require_user();$uid=user_id();$conn->query("UPDATE notifikasi SET is_read=1 WHERE id_user=".$uid);$s=$conn->prepare('SELECT * FROM notifikasi WHERE id_user=? ORDER BY created_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifikasi</title><style>body{font-family:Arial;background:#f4f6f9}.wrap{max-width:800px;margin:40px auto}.card{background:#fff;padding:20px;border-radius:12px;margin-bottom:12px}.back{display:inline-block;margin-bottom:15px;background:#1e3a8a;color:#fff;padding:10px 15px;border-radius:8px;text-decoration:none}.date{font-size:.8rem;color:#999}</style></head><body><div class="wrap"><a class="back" href="dashboard.php">← Dashboard</a><h1 style="color:#1e3a8a">Notifikasi</h1><?php while($r=$rows->fetch_assoc()):?><div class="card"><h3><?=e($r['judul'])?></h3><p><?=nl2br(e($r['pesan']))?></p><div class="date"><?=e($r['created_at'])?></div></div><?php endwhile;?></div></body></html>
